namespace ghidra.app.context;

using docking;
using ghidra.app.nav;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;

public class NavigatableActionContext : ProgramLocationActionContext, NavigationActionContext {
	private Navigatable navigatable;

	public NavigatableActionContext(ComponentProvider provider, Navigatable navigatable) : base(provider, navigatable.getProgram(), navigatable.getLocation(),
			navigatable.getSelection(), navigatable.getHighlight())
    {
		this.navigatable = navigatable;
	}

	public NavigatableActionContext(ComponentProvider provider, Navigatable navigatable,
			ProgramLocation location) : base(provider, navigatable.getProgram(), location, navigatable.getSelection(),
			navigatable.getHighlight())
    {
		this.navigatable = navigatable;
	}

	public NavigatableActionContext(ComponentProvider provider, Navigatable navigatable,
			Program program, ProgramLocation location, ProgramSelection selection,
			ProgramSelection highlight) : base(provider, program, location, selection, highlight)
    {
		this.navigatable = navigatable;
	}

	public Navigatable getNavigatable() {
		return navigatable;
	}

	/**
	 * Overridden to signal that this navigatable's program may not be the same as the globally 
	 * active program.  This is done to signal that this navigatable can supply default context.
	 * 
	 * @return false
	 */
	/* @Override */
	public bool isActiveProgram() {
		// signal that our program may be different than the active program
		return navigatable.isConnected();
	}
